const raw = $input.first().json;
const b = raw.body;
const plain = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const requestId = plain(b) && typeof b.requestId === 'string' && uuid.test(b.requestId) ? b.requestId : null;
const fail = (code,message,status=400) => [{json:{valid:false,status,body:{version:1,requestId,error:{code,message,retryable:status>=500}}}}];
if (!plain(b) || b.version !== 1 || !requestId || typeof b.message !== 'string' || !b.message.trim() || b.message.length>2000) return fail('INVALID_REQUEST','Envía un mensaje de entre 1 y 2000 caracteres con el formato del chat.');
if (JSON.stringify(b).length>12000 || !plain(b.context)) return fail('INVALID_REQUEST','El contexto del mensaje no es válido.');
if (b.conversationId !== null && b.conversationId !== undefined && (typeof b.conversationId!=='string' || !/^lrmq_[a-f0-9]{64}$/.test(b.conversationId))) return fail('INVALID_REQUEST','La conversación no es válida.');
const c=b.context;
if(typeof c.pagePath!=='string' || !/^(\/|\/productos(?:\/[a-z0-9]+(?:-[a-z0-9]+)*)?)$/.test(c.pagePath) || c.pagePath.length>240) return fail('INVALID_REQUEST','La página del mensaje no es válida.');
const slug=c.productSlug ?? null;
if(slug!==null && (typeof slug!=='string' || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug) || slug.length>180 || c.pagePath!=='/productos/'+slug)) return fail('INVALID_REQUEST','El producto del contexto no es válido.');
const filters={};
const allowed=['search','category','supplier','brand','subcategory','collection','finish','measure','shape','has_led','distribution','product_kind','commercial_mode','modularity','texture','color','grille','orientation'];
if(c.filters!==undefined && !plain(c.filters)) return fail('INVALID_REQUEST','Los filtros no son válidos.');
for(const k of allowed) {
 const v=c.filters?.[k];
 if(typeof v==='string') filters[k]=v.slice(0,120);
 else if(Array.isArray(v)) filters[k]=v.filter(x=>typeof x==='string').slice(0,6).map(x=>x.slice(0,120));
}
let conversationId=b.conversationId;
if(!conversationId) {
 if(typeof raw.sessionNonce!=='string' || !/^[a-f0-9]{64}$/.test(raw.sessionNonce)) return fail('CHAT_UNAVAILABLE','El servicio de chat todavía no está disponible.',503);
 conversationId='lrmq_'+raw.sessionNonce;
}
const context={pagePath:c.pagePath,productSlug:slug,filters,locale:'es'};
return [{json:{valid:true,requestId,conversationId,message:b.message.trim(),context,agentInput:JSON.stringify({message:b.message.trim(),context})}}];

const source=$('Validar entrada').first().json;
const result=$input.first().json;
const fail=()=>[{json:{status:503,body:{version:1,requestId:source.requestId,error:{code:'CHAT_UNAVAILABLE',message:'Ahora mismo no podemos responder. Puedes contactar con el personal desde la web.',retryable:true}}}}];
let answer=result.output;
if(result.error) return fail();
if(typeof answer==='string') {try {answer=JSON.parse(answer);} catch {return fail();}}
if(!answer || typeof answer.message!=='string' || !answer.message.trim() || answer.message.length>4000 || !Array.isArray(answer.recommendations) || answer.recommendations.length>3 || !Array.isArray(answer.actionKeys)) return fail();
const unsafe=t=>/https?:|www\.|mailto:|javascript:|data:|<[^>]*>|\]\s*\(|(?:\b[a-z0-9-]+\.)+(?:com|es|net|org|io|dev|app|eu)\b|€|\b(?:EUR|USD)\b|\b\d[\d., ]*\s*(?:euros?|d[oó]lares?)\b/i.test(t);
if(unsafe(answer.message)) return fail();
const evidence=new Map();
const collect=(v,depth=0)=>{
 if(depth>8 || v===null || v===undefined) return;
 if(typeof v==='string') {if(v.length>100000)return; try{collect(JSON.parse(v),depth+1);}catch{} return;}
 if(Array.isArray(v)){for(const item of v)collect(item,depth+1);return;}
 if(typeof v==='object'){
  if(typeof v.slug==='string' && typeof v.productId==='string' && typeof v.name==='string' && Array.isArray(v.variants) && v.availability==='listed_not_stock_confirmed') evidence.set(v.slug,v);
  for(const k of ['json','result','items','data','response','output'])if(v[k]!==undefined)collect(v[k],depth+1);
 }
};
for(const s of result.intermediateSteps??[]){
 if(s.action?.tool==='Obtener_producto') collect(s.observation);
}
const products=[];
const seen=new Set();
for(const rec of answer.recommendations){
 if(!rec || typeof rec.slug!=='string' || typeof rec.reason!=='string' || rec.reason.length>500 || unsafe(rec.reason))return fail();
 const p=evidence.get(rec.slug);
 if(!p || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(p.slug) || unsafe(p.name))return fail();
 if(seen.has(p.slug))continue;
 seen.add(p.slug);
 const facts=[];
 if(Array.isArray(p.measures) && p.measures.length){
  const labels=p.measures.slice(0,8).map(m=>typeof m==='string'?m:(typeof m?.length_cm==='number' && typeof m?.width_cm==='number'?m.length_cm+' × '+m.width_cm+' cm':null)).filter(Boolean);
  if(labels.length)facts.push('Medidas publicadas: '+labels.join(', ')+(p.measures.length>8?'…':''));
 }
 if(Array.isArray(p.finishes)&&p.finishes.length)facts.push('Acabados: '+p.finishes.filter(f=>typeof f==='string').slice(0,6).join(', '));
 if(facts.some(unsafe))return fail();
 products.push({productId:p.productId,slug:p.slug,name:p.name,internalPath:'/productos/'+p.slug,facts,recommendationReason:rec.reason});
}
const allowed={
 catalogo:{type:'navigate_internal',label:'Explorar catálogo',target:'/productos'},
 reformas:{type:'navigate_internal',label:'Ver reformas',target:'/#reformas'},
 contacto:{type:'navigate_internal',label:'Contactar con Area LRMQ',target:'/#contacto'},
 whatsapp:{type:'contact_official',label:'Hablar por WhatsApp',target:'https://wa.me/34629461032'}
};
if(answer.actionKeys.some(k=>typeof k!=='string'||!Object.hasOwn(allowed,k)))return fail();
const actions=[...new Set(answer.actionKeys)].slice(0,3).map(k=>allowed[k]);
return [{json:{status:200,body:{version:1,conversationId:source.conversationId,requestId:source.requestId,message:answer.message.trim(),products,actions}}}];

